// sum of 1..n
int sumTo(int n) {
    if (n == 0) return 0;               // base case
    return n + sumTo(n - 1);            // recursive case
}

// power
int power(int base, int exp) {
    if (exp == 0) return 1;             // base case
    return base * power(base, exp - 1);
}

// gcd (Euclid)
int gcd(int a, int b) {
    if (b == 0) return a;               // base case
    return gcd(b, a % b);
}

// Fibonacci: two recursive calls
int fib(int n) {
    if (n <= 1) return n;               // base cases 0 and 1
    return fib(n - 1) + fib(n - 2);
}

// digits: n % 10 = last digit, n / 10 = the rest
int sumDigits(int n) {
    if (n == 0) return 0;
    return n % 10 + sumDigits(n / 10);
}

