#include <iostream>
using namespace std;

int sumTo(int n) {
    if (n == 0) {
        return 0;
    }
    return n + sumTo(n - 1);
}

int power(int base, int exp) {
    if (exp == 0) {
        return 1;
    }
    return base * power(base, exp - 1);
}

void printReversed(int n) {
    if (n == 0) {
        return;
    }
    cout << n % 10;
    printReversed(n / 10);
}

int main() {
    cout << "Sum of 1..5 = " << sumTo(5) << endl;
    cout << "2 to the power 5 = " << power(2, 5) << endl;
    cout << "472 reversed = ";
    printReversed(472);
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int calls = 0;

int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

int fib(int n) {
    calls++;
    if (n <= 1) {
        return n;
    }
    return fib(n - 1) + fib(n - 2);
}

int main() {
    cout << "gcd(8, 12) = " << gcd(8, 12) << endl;
    cout << "fib(6) = " << fib(6) << endl;
    cout << "calls = " << calls << endl;
    return 0;
}

